const token = jwt.sign({ role: 'user' }, 'demo-secret',
  { expiresIn: '15m' });
const [head, , sig] = token.split('.');
const body = Buffer.from('{"role":"admin"}').toString('base64url');
const forged = `${head}.${body}.${sig}`;
console.log(jwt.decode(forged).role);
try { jwt.verify(forged, 'demo-secret'); }
catch (err) { console.log(err.message); }
